      const low = voicing[0]
      const mid = voicing[1]
      const high = voicing[2]
      const bhz = bassHz(root)
      const ahz = acidHz(root)
      const slide = prevRoot === null || prevRoot === root ? 0 : 1
      prevRoot = root
