      for (const beat of [0, 2]) {
        add(at, beat, 0.5, 87, 'kick', 0)
        add(at, beat, 0.5, 87, '808', 0)
      }
      for (const beat of [1, 3]) add(at, beat, 0.5, 174, 'snare', 0)
      for (const beat of [0, 0.5, 1, 1.5, 2, 2.5, 3, 3.5]) add(at, beat, 0.5, 4560, 'hat', 0)
