      add(at, 1.5, 0.25, 528, 'tablaDayan', 0)
      add(at, 3, 0.25, 528, 'tablaDayan', 0)
      add(at, 0, 0.5, 174, 'mridangam', 0)
      add(at, 2.5, 0.25, 285, 'mridangam', 0)
