  events.sort((a, b) => (
    a.bar - b.bar
    || a.beat - b.beat
    || (a.voice < b.voice ? -1 : a.voice > b.voice ? 1 : 0)
    || a.hz - b.hz
    || a.durBeats - b.durBeats
    || a.gain - b.gain
    || a.slide - b.slide
  ))

